// Data-driven piece-type definitions consumed by src/lib/engine.ts.
//
// Every visible sign-type sheet in the blank workbook maps to one entry here.
// Formulas are transcribed from docs/17-estimating-piece-formulas.md (which is
// auto-generated by scripts/dump-piece-formulas.py from the blank workbook).
//
// The four formulas explicitly anchored in docs/16-estimating.md are
// "verified" types with covering unit tests in src/__tests__/engine.test.ts.
// The rest are "implemented-from-workbook" types — their math follows the
// workbook formulas as faithfully as possible, but only spot-tested. Anything
// that's genuinely ambiguous in the workbook is flagged with a // TODO and a
// cell reference, per the build spec.

import { RATES, TABLES, tierFor, type RateTier } from './rates';

// ---------------------------------------------------------------------------
// Shapes
// ---------------------------------------------------------------------------

export type InputKind = 'number' | 'integer' | 'text' | 'select';

export interface InputDef {
  readonly key: string;
  readonly label: string;
  readonly kind: InputKind;
  readonly default?: number | string;
  readonly min?: number;
  readonly max?: number;
  readonly options?: readonly { value: string; label: string }[];
  readonly unit?: string;
  readonly help?: string;
}

export interface ComputedLaborLine {
  readonly workCode: number;
  readonly description?: string;
  readonly hours: number;
}

export interface ComputedMaterialLine {
  readonly itemNo: string;
  readonly description?: string;
  readonly units: number;
  readonly unitPrice?: number;
  readonly unitCost?: number;
  readonly profitPct?: number;
}

export interface ComputedPiece {
  readonly sqft: number;
  readonly labor: readonly ComputedLaborLine[];
  readonly materials: readonly ComputedMaterialLine[];
  readonly notes?: readonly string[];
}

export type PieceCompute = (inputs: Record<string, number | string>) => ComputedPiece;

export interface PieceTypeDef {
  readonly id: string;
  readonly label: string;
  readonly workbookSheet: string;
  readonly status: 'verified' | 'implemented' | 'todo';
  readonly inputs: readonly InputDef[];
  readonly compute: PieceCompute;
  readonly references?: readonly string[];
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** CEILING(x, step) — round x up to the nearest multiple of step.
 *  Mirrors Excel's CEILING(value, significance). */
export function ceilingMultiple(x: number, step: number): number {
  if (step <= 0) return x;
  if (x <= 0) return 0;
  return Math.ceil(x / step) * step;
}

/** CEILING(value / rate, B84). B84 is RATES.hourRoundingFactor = 0.25. */
function laborHours(units: number, ratePerHour: number): number {
  if (units <= 0 || ratePerHour <= 0) return 0;
  return ceilingMultiple(units / ratePerHour, RATES.hourRoundingFactor);
}

function num(inputs: Record<string, number | string>, key: string, fallback = 0): number {
  const v = inputs[key];
  if (typeof v === 'number' && Number.isFinite(v)) return v;
  if (typeof v === 'string' && v.trim() !== '') {
    const n = Number(v);
    if (Number.isFinite(n)) return n;
  }
  return fallback;
}

function str(inputs: Record<string, number | string>, key: string, fallback = ''): string {
  const v = inputs[key];
  return typeof v === 'string' ? v : fallback;
}

