// Auto-applied EST PAINT - CUSTOM material line. The catalog price is
// $0.051/unit (gram). For extra paint colors we apply
// units = paint_area_sqft * grams_per_sqft * extraColors * extraPaintPct
// per the workbook's "extra paint color materials" formula
// (=B5*F46*B57*B49 in Post-and-panel etc.).
function extraPaintMaterial(extraColors: number, paintAreaSqft: number): ComputedMaterialLine | null {
  if (extraColors <= 0 || paintAreaSqft <= 0) return null;
  const grams = Math.round(
    paintAreaSqft * RATES.paintGramsPerSqft * RATES.extraPaintColorPct * extraColors
  );
  if (grams <= 0) return null;
  return {
    itemNo: 'EST PAINT - CUSTOM',
    description: 'Estimate for Custom Paint Color',
    units: grams,
    unitCost: 0.02856,
    unitPrice: 0.051,
    profitPct: 44.45,
  };
}

