const FLAT_PANELS_ONLY: PieceTypeDef = {
  id: 'flat-panels',
  label: 'Flat panels only',
  workbookSheet: 'Flat panels only',
  status: 'implemented',
  references: ['B33 G=IF(plastic, ceil(E33/F33,B84); B34 G=IF(metal, ceil(E34/F34,B84)'],
  inputs: [
    COMMON_HW.H, COMMON_HW.L,
    { key: 'panels', label: 'Number of panels', kind: 'integer', default: 1, min: 1 },
    {
      key: 'material',
      label: 'Panel material',
      kind: 'select',
      default: 'Acrylic',
      options: [
        { value: 'Acrylic', label: 'Acrylic (72 sqft/hr)' },
        { value: 'Polycarbonate', label: 'Polycarbonate (48 sqft/hr)' },
        { value: 'ACM', label: 'ACM (96 sqft/hr)' },
        { value: 'Pre-Paint Aluminum', label: 'Pre-paint aluminum (96 sqft/hr)' },
      ],
    },
  ],
  compute: (inputs) => {
    const H = num(inputs, 'H');
    const L = num(inputs, 'L');
    const panels = Math.max(1, Math.round(num(inputs, 'panels', 1)));
    const material = str(inputs, 'material', 'Acrylic');
    const sqft = (H * L / 144) * panels;
    const procSqft = ceilingMultiple(sqft, 10);
    const rateByMaterial: Record<string, number> = {
      Acrylic: RATES.acrylicCutSqftPerHour,
      Polycarbonate: RATES.polycarbCutSqftPerHour,
      ACM: RATES.acmCutSqftPerHour,
      'Pre-Paint Aluminum': RATES.prepaintedAlumCutSqftPerHour,
    };
    const rate = rateByMaterial[material] ?? RATES.acrylicCutSqftPerHour;
    const isPlastic = material === 'Acrylic' || material === 'Polycarbonate';
    const labor: ComputedLaborLine[] = isPlastic
      ? [{ workCode: 2312, description: 'Plastic Face Labor', hours: laborHours(procSqft, rate) }]
      : [{ workCode: 2011, description: 'Cabinet Metal Labor', hours: laborHours(procSqft, rate) }];
    return { sqft, labor, materials: [] };
  },
};

