const LED_WIRING: PieceTypeDef = {
  id: 'led-wiring',
  label: 'LED wiring',
  workbookSheet: 'LED wiring',
  status: 'implemented',
  references: ['Synergy: 1.3 LEDs/sqft, 108 LEDs/PSU. Quickmod: 1.5/50.'],
  inputs: [
    COMMON_HW.H, COMMON_HW.L, COMMON_HW.qty,
    {
      key: 'ledFamily',
      label: 'LED family',
      kind: 'select',
      default: 'synergy',
      options: [...LED_FAMILY_OPTIONS],
    },
  ],
  compute: (inputs) => {
    const H = num(inputs, 'H');
    const L = num(inputs, 'L');
    const qty = Math.max(1, Math.round(num(inputs, 'qty', 1)));
    const family = str(inputs, 'ledFamily', 'synergy');
    const sqft = (H * L / 144) * qty;
    const ledsPerSqft = family === 'quickmod' ? RATES.quickmodLedsPerSqft : RATES.synergyLedsPerSqft;
    const ledsPerPSU = family === 'quickmod' ? RATES.quickmodLedsPerPowerSupply : RATES.synergyLedsPerPowerSupply;
    const leds = Math.ceil(sqft * ledsPerSqft);
    const psus = leds > 0 ? Math.ceil(leds / ledsPerPSU) : 0;
    return {
      sqft,
      labor: [{ workCode: 2212, description: 'LED Wiring Labor', hours: laborHours(sqft, RATES.ledWiringSqftPerHour) }],
      materials: [
        { itemNo: `LED-${family}`, description: `${family === 'quickmod' ? 'Quickmod 12V' : 'Synergy 24V'} LEDs`, units: leds, unitPrice: 0, unitCost: 0, profitPct: 0 },
        { itemNo: `PSU-${family}`, description: `${family === 'quickmod' ? 'Quickmod 12V' : 'Synergy 24V'} Power Supply`, units: psus, unitPrice: 0, unitCost: 0, profitPct: 0 },
      ],
    };
  },
};

