interface CabinetOptions {
  readonly fabTable: readonly RateTier[];
  readonly fabWorkCode?: number;
  readonly facePaintMultiplier: 1 | 2;
  readonly routed?: boolean;
  readonly acrylic?: boolean;
  readonly flex?: boolean;
}

function cabinetCompute(inputs: Record<string, number | string>, opts: CabinetOptions): ComputedPiece {
  const H = num(inputs, 'H');
  const L = num(inputs, 'L');
  const qty = Math.max(1, Math.round(num(inputs, 'qty', 1)));
  const D = num(inputs, 'D');
  const shape = str(inputs, 'shape', 'Rectangular');
  const extraColors = Math.max(0, Math.round(num(inputs, 'extraColors', 0)));
  const inchesOfCopy = num(inputs, 'inchesOfCopy', 0);
  const pushThrough = str(inputs, 'pushThrough', 'No').toLowerCase() === 'yes';
  const dividerRows = Math.max(0, Math.round(num(inputs, 'dividerRows', 0)));
  const faces = opts.facePaintMultiplier;
  const sqft = (H * L / 144) * qty;
  const perimeterFt = (((H + L) * 2) / 12) * qty;
  const faceSqft = sqft * faces;
  const fillerSqft = (D / 12) * perimeterFt;
  const paintArea = faceSqft + fillerSqft;
  const fabRate = tierFor(opts.fabTable, sqft);
  const fabHours = laborHours(sqft, fabRate);
  const radiusHours = shape === 'Radius/Angle' ? fabHours * RATES.radiusOrAngleExtraLaborPct : 0;
  const fabWC = opts.fabWorkCode ?? 2011;
  const labor: ComputedLaborLine[] = [];
  if (opts.routed) {
    const setup = sqft > 0 ? RATES.routerSetupHours * 2 : 0;
    labor.push({ workCode: 2010, description: 'Routing setup', hours: setup });
    const copyInches = inchesOfCopy * RATES.letterPerimeterPathFactor * qty;
    labor.push({ workCode: 2010, description: 'Aluminum copy routing', hours: laborHours(copyInches, RATES.routingAluminumInchesPerHour) });
    labor.push({ workCode: 2010, description: 'Acrylic backer routing', hours: pushThrough ? 0 : laborHours(sqft, RATES.routedPanelShapeSqftPerHour) });
    labor.push({ workCode: 2010, description: 'Push-through routing', hours: pushThrough ? laborHours(copyInches, RATES.routingPushThroughInchesPerHour) : 0 });
  }
  labor.push({ workCode: fabWC, description: 'Cabinet Metal Labor', hours: fabHours });
  if (radiusHours > 0) labor.push({ workCode: fabWC, description: 'Radius/Angle uplift', hours: radiusHours });
  labor.push({ workCode: 2110, description: 'Paint Prep Labor', hours: laborHours(paintArea, RATES.cabinetPaintPrepSqftPerHour) });
  labor.push({ workCode: 2112, description: 'Paint Cabinet & Letters Labor', hours: laborHours(paintArea, RATES.cabinetPaintSqftPerHour) });
  labor.push({ workCode: 2212, description: 'LED Wiring Labor', hours: laborHours(faceSqft, RATES.ledWiringSqftPerHour) });
  if (opts.acrylic || opts.flex) {
    labor.push({ workCode: 2215, description: 'Assembly Labor', hours: laborHours(perimeterFt, RATES.retainerAssemblySqftPerHour) });
  } else {
    labor.push({ workCode: 2215, description: 'Assembly Labor', hours: laborHours(faceSqft, RATES.flexFaceAssemblySqftPerHour) });
  }
  if (opts.acrylic) labor.push({ workCode: 2312, description: 'Plastic Face Labor', hours: laborHours(faceSqft, RATES.acrylicCutSqftPerHour) });
  if (opts.flex) labor.push({ workCode: 2316, description: 'Flex Face Assembly Labor', hours: laborHours(faceSqft, RATES.flexFaceAssemblySqftPerHour) });
  if (opts.routed) labor.push({ workCode: 2313, description: 'Routed pop stud labor', hours: laborHours(sqft, RATES.routedPopStudSqftPerHour) });
  if (dividerRows > 0 && opts.acrylic) {
    const dividerFt = (dividerRows * L / 12) * qty;
    labor.push({ workCode: 2011, description: 'Divider bar labor', hours: laborHours(dividerFt, RATES.dividerBarFtPerHour) });
  }
  if (extraColors > 0 && paintArea > 0) labor.push({ workCode: 2110, description: 'Extra color masking', hours: extraColors });
  const materials: ComputedMaterialLine[] = [];
  const paint = extraPaintMaterial(extraColors, paintArea);
  if (paint) materials.push(paint);
  return { sqft, labor, materials };
}

function cabinetInputs(extras: readonly InputDef[] = []): readonly InputDef[] {
  return [
    { key: 'shape', label: 'Shape', kind: 'select', default: 'Rectangular', options: [...SHAPE_OPTIONS] },
    { key: 'extraColors', label: 'Extra paint colors', kind: 'integer', default: 0, min: 0 },
    { key: 'qty', label: 'Number of signs', kind: 'integer', default: 1, min: 1 },
    COMMON_HW.H, COMMON_HW.L,
    { key: 'D', label: 'Depth', kind: 'number', default: 6, min: 0, unit: 'in' },
    ...extras,
  ];
}

