export const PIECE_TYPES: readonly PieceTypeDef[] = Object.freeze([
  FREEFORM_TM,
  APPLY_VINYL_GRAPHICS,
  VINYL_CUTTING,
  PAINT_CALCULATION,
  ROUTED_PANEL_SHAPES,
  ALUM_PAN_SIGN,
  ECONOMY_PAN_SIGN,
  POST_AND_PANEL,
  FLAT_PANELS_ONLY,
  ROUTED_FACE_ONLY,
  ROUTED_ALUM_FACES_LETTERS,
  ROUTED_PUSH_THROUGH_ACRYLIC,
  SF_ROUTED_CABINET,
  DF_ROUTED_CABINET,
  SF_ACRYLIC_CABINET,
  ECONOMY_SF_ACRYLIC,
  DF_ACRYLIC_CABINET,
  SF_FLEX_CABINET,
  DF_FLEX_CABINET,
  POLE_COVER,
  STRUCTURAL_STEEL_FAB,
  REVEAL,
  CROWN_COVE,
  EMC_ASSEMBLY,
  CRATING,
  LED_WIRING,
  CHANGEABLE_COPY_FACE,
  FLEX_FACE_ASSEMBLY,
  ROUTED_FACE_ASSEMBLY,
  TRIMCAP_LETTER_FACE,
  CHANNEL_LETTER_FABRICATION,
]);

export const PIECE_TYPE_BY_ID: ReadonlyMap<string, PieceTypeDef> = new Map(
  PIECE_TYPES.map(t => [t.id, t])
);

export function getPieceType(id: string): PieceTypeDef | undefined {
  return PIECE_TYPE_BY_ID.get(id);
}

